# Builds engine-t3-research.src.js from a byte snapshot of Codex's T3 bundle (cage-t3-3, commit 7e14dbb).
# Every candidate mechanism is behind a flag in T3R_FLAGS; with no flags the engine is identical to T3
# (verified by tools/claude-t3-research.cjs --identity). Research only: never copied into src/.
#   python proposals/t3-research/make_research.py
import os
D = os.path.dirname(os.path.abspath(__file__)) + '/'
s = open(D + 'base-cage-t3-3.js', encoding='utf8').read()

def rep(a, b, count=1):
    global s
    assert s.count(a) == count, (s.count(a), a)
    s = s.replace(a, b)

HEAD = "// GENERATED by tools/build-t3.cjs."
rep(HEAD, "// T3 RESEARCH COPY (Claude, reference only, NOT production). Built by proposals/t3-research/make_research.py.\n"
          "const RF=(typeof T3R_FLAGS!=='undefined'?T3R_FLAGS:{});\n" + HEAD)

# ---------- C2 / C3: parameter flags ----------
rep("press:{rest:-1,", "press:{rest:RF.C2?0:-1,")
rep("const P={k:22,clampLo:.12,clampHi:.88,", "const P={k:RF.Q1?20:22,clampLo:RF.Q1?.10:.12,clampHi:RF.Q1?.90:.88,")
rep("fatigueScale:140,", "fatigueScale:RF.C3?55:140,")

# ---------- state ----------
rep("let t=0,poss=0,carrier=null,", "let scramble=false,receivedFree=false,pressedHigh=false,t=0,poss=0,carrier=null,")

# D4 urgency: commitment +1 for both teams once urgency > .35 (symmetric; spike constants)
rep("const zone=()=>({x,lane:['left','centre','right'][lane]}),context=()=>S.context(T,poss,carrier,zone());",
    "const zone=()=>({x,lane:['left','centre','right'][lane]}),context=()=>S.context(T,poss,carrier,zone());\n"
    "const urg=()=>RF.D4?lim((t-150)/60*.12,0,.8):0;\n"
    "const commitU=team=>{S.commitment(team);if(RF.D4&&urg()>.35){const q=team.ps.filter(p=>!p.committed).sort((a,b)=>(b.c.ATT-b.c.DEF)-(a.c.ATT-a.c.DEF))[0];if(q&&team.ps.filter(p=>!p.committed).length>1)q.committed=true;}};")
rep("for(const team of T){S.commitment(team);team.ps.forEach(q=>q.oop=0);}",
    "scramble=false;receivedFree=false;pressedHigh=false;for(const team of T){commitU(team);team.ps.forEach(q=>q.oop=0);}")
# turnover: reset flags, D3 regainer joins the attack when the opponent is actually caught upfield
rep("T[poss].ps.forEach(q=>q.oop=0);S.commitment(T[poss]);",
    "scramble=false;receivedFree=false;pressedHigh=false;T[poss].ps.forEach(q=>q.oop=0);commitU(T[poss]);if(RF.D3&&transition&&caught.length>=1)winner.committed=true;")

# ---------- D5 scramble after an attacking rebound ----------
rep("if(r.win){carrier=att;x=3;lane=1;carrier.pos=S.world(zone(),poss);}else turnover(def,'rebound','second_ball');",
    "if(r.win){carrier=att;x=3;lane=1;carrier.pos=S.world(zone(),poss);if(RF.D5||RF.D5b)scramble=true;}else turnover(def,'rebound','second_ball');")
rep("const base=kind==='fk'?P.shot.fk:",
    "const base=kind==='scramble'?(RF.D5b?P.shot.box.C:-.1):kind==='fk'?P.shot.fk:")
rep("quality=kind==='box'||kind==='one_v_one'?eff(sh,'shot'):eff(sh,'long')",
    "quality=kind==='scramble'?(RF.D5b?.7*eff(sh,'shot')+.3*sh.c.a.phys:.5*eff(sh,'shot')+.5*sh.c.a.phys):kind==='box'||kind==='one_v_one'?eff(sh,'shot'):eff(sh,'long')")

# ---------- D6 corners from blocked shots ----------
rep("emit({type:'block',team:1-poss,actor:bl.id,opp:sh.id,p:r.p,roll:r.roll,outcome:'blocked',roles:{blocker:bl.id},calc:r.calc},ctx,true);return loose('block');",
    "emit({type:'block',team:1-poss,actor:bl.id,opp:sh.id,p:r.p,roll:r.roll,outcome:'blocked',roles:{blocker:bl.id},calc:r.calc},ctx,true);if(RF.D6&&R()<.35)return corner();return loose('block');")
rep("function loose(source){",
    "function corner(){const air=q=>.5*q.c.a.phys+.3*q.c.a.finish+.2*q.c.a.com,mark=q=>.5*q.c.a.phys+.3*q.c.a.mrk+.2*q.c.a.def,att=T[poss].ps.slice().sort((a,b)=>air(b)-air(a))[0],def=T[1-poss].ps.slice().sort((a,b)=>mark(b)-mark(a))[0];t+=P.dt.restart;x=3;lane=1;carrier=att;carrier.pos=S.world(zone(),poss);lastPasser=null;emit({type:'corner',team:poss,actor:att.id,zone:zone()});"
    "const r=duel(air(att),mark(def),-.3);emit({type:'aerial_duel',team:poss,actor:att.id,opp:def.id,p:r.p,roll:r.roll,outcome:r.win?'attacker_wins':'defender_wins',calc:r.calc});if(!r.win)return turnover(def,'clearance','corner_cleared');"
    "emit({type:'shot_attempt',team:poss,actor:att.id,zone:zone(),kind:'header',pressure:def.id});t+=P.dt.shot;const z=-1.8+(air(att)-F_AIRREF)/P.shot.q,p=lim(logistic(z),.01,.8),roll=R();"
    "if(roll<p){score[poss]++;emit({type:'goal',team:poss,actor:att.id,p,roll,kind:'header',zone:zone(),assist:null,transition:false,calc:{logit:rounded(z)}});over=mode==='ko';if(!over)restart(1-poss,'kickoff');return;}"
    "emit({type:'shot_miss',team:poss,actor:att.id,p,roll,kind:'header',outcome:'wide'});return turnover(def,'clearance','header_missed');}\n"
    "function loose(source){")
s = s.replace("F_AIRREF", "75")

# ---------- step(): flags consumed at decision time ----------
rep("const c=carrier,pol=T[poss].policy,dpol=T[1-poss].policy,ctx=context(),d=ctx.d,",
    "if((RF.D5||RF.D5b)&&scramble){scramble=false;if(R()<.6)return shoot('scramble');}\n"
    "const rf=receivedFree;receivedFree=false;const ck=checked;checked=false;\n"
    "const c=carrier,pol=T[poss].policy,dpol=T[1-poss].policy,ctx=context(),d=ctx.d,")
rep("engaged=!!d&&R()<engage,", "engaged=!!d&&(R()<engage||(RF.B5&&ck))&&!(RF.B2&&rf),")
# C1: a high press that engages in the carrier's own half is recorded; beating it opens a transition
rep("if(transition&&runner)U.outlet=Q.outlet*pol.directness;",
    "if(transition&&runner)U.outlet=Q.outlet*pol.directness;\n"
    "if(RF.C1&&engaged&&x<=1&&T[1-poss].tac.engageHigh>.5)pressedHigh=true;\n"
    "if(RF.A2&&engaged&&x===3&&ctx.support.length&&ctx.attackers>ctx.defenders)U.cutback=(.3+(c.c.pass-70)/30)*ctx.support.length*pol.riskAppetite;\n"
    "let freeMan=null;if(RF.A2t&&engaged&&x>=2){const sup=mates.filter(q=>q.oop===0&&(q.committed||S.oriented(q.pos,poss)>=2)),markers=T[1-poss].ps.filter(q=>q.oop===0&&q!==d&&q!==ctx.helper);if(sup.length>markers.length){const gap=q=>markers.length?Math.min(...markers.map(m=>S.dist(m.pos,q.pos))):9;freeMan=sup.slice().sort((a,b)=>gap(b)-gap(a)||b.c.shot-a.c.shot)[0];U.cutback=(.3+(c.c.pass-70)/30)*(sup.length-markers.length)*pol.riskAppetite;}}")
# D1: discipline depends on actual cover behind the ball, not on the commitment label alone
rep("const discipline=!c.committed?(x>=2?Q.boxDiscipline:Q.deepDiscipline):Q.committedDiscipline;for(const k of ['carry','dribble','shoot','wall'])if(U[k]!==undefined)U[k]*=discipline;if(!c.committed)U.pass*=Q.restPass;",
    "const covered=mates.filter(q=>q.oop===0&&S.oriented(q.pos,poss)<x).length>=1;let discipline=!c.committed?(x>=2?Q.boxDiscipline:Q.deepDiscipline):Q.committedDiscipline;if(RF.D1&&!c.committed&&covered)discipline=1;for(const k of ['carry','dribble','shoot','wall'])if(U[k]!==undefined)U[k]*=(RF.D1b&&!c.committed&&covered&&(k==='carry'||k==='shoot'))?1:discipline;if(!c.committed&&!(RF.D1&&covered))U.pass*=Q.restPass;\n"
    "if(RF.D4){const u=1+urg();for(const k of ['shoot','dribble','through','wall','cutback'])if(U[k]!==undefined)U[k]*=u;}")
# A2: cut-back to the free man created by an overload (receiver faces only defenders actually near him)
rep("if(action==='shoot')return shoot(!d?'one_v_one':x===3?'box':'edge');",
    "if(action==='shoot')return shoot(!d?'one_v_one':x===3?'box':'edge');\n"
    "if(action==='cutback'){const recv=freeMan||ctx.support.slice().sort((a,b)=>b.c.shot-a.c.shot)[0],near=T[1-poss].ps.filter(q=>q.oop===0&&q!==d&&S.dist(q.pos,recv.pos)<=1).sort((a,b)=>S.dist(a.pos,recv.pos)-S.dist(b.pos,recv.pos)||b.c.intercept-a.c.intercept),ic=near[0]||null;t+=P.dt.pass;tire(c,'pass');"
    "const r=ic?duel(.75*eff(c,'pass')+.25*(recv.c.a.agi+recv.c.a.pace)/2,eff(ic,'intercept'),1.0):{p:1,roll:R(),win:true,calc:{}};const to={x:S.oriented(recv.pos,poss),lane:['left','centre','right'][recv.pos.y]};"
    "emit({type:'pass',team:poss,actor:c.id,target:recv.id,opp:ic?.id||null,p:r.p,roll:r.roll,zone:zb,to,outcome:r.win?'complete':'intercepted',tags:['cutback'],roles:{receiver:recv.id},calc:{...r.calc,weights}},ctx);"
    "if(r.win){lastPasser=c.id;d.oop=Math.max(d.oop,1);if(RF.A2t&&ctx.helper&&ctx.helper!==ic)ctx.helper.oop=Math.max(ctx.helper.oop,1);carrier=recv;x=to.x;lane=recv.pos.y;return shoot(x===3?'box':'edge');}return turnover(ic,'interception','read_cutback');}")
# C1 consequences
rep("if(r.win){d.oop=1;if(x<3)x++;c.pos=S.world(zone(),poss);return;}",
    "if(r.win){d.oop=1;if(x<3)x++;c.pos=S.world(zone(),poss);if(RF.C1&&pressedHigh&&x>=2){transition=true;d.oop=2;pressedHigh=false;events.at(-1).tags.push('press_bypassed');}return;}")
rep("if(r.win)return turnover(d,'press_win','press');d.oop=1;return;}",
    "if(r.win)return turnover(d,'press_win','press');d.oop=1;if(RF.C1&&pressedHigh){transition=true;d.oop=2;pressedHigh=false;events.at(-1).tags.push('press_bypassed');}return;}")
# B2 receive in space / C1 bypass by pass
rep("if(r.win){lastPasser=c.id;carrier=receiver;x=to.x;lane=receiver.pos.y;",
    "if(r.win){lastPasser=c.id;carrier=receiver;x=to.x;lane=receiver.pos.y;"
    "if(RF.C1&&pressedHigh&&x>=2){transition=true;pressedHigh=false;events.at(-1).tags.push('press_bypassed');}"
    "if(RF.B2&&action==='pass'&&R()<lim(.10+(eff(c,'pass')-75)/35+(receiver.c.a.agi-75)/70,.03,.75))receivedFree=true;")
rep("+(ctx.d?P.shot.pressure:0)","+(ctx.d&&!(RF.D5b&&kind==='scramble')?P.shot.pressure:0)")
# B4t: passes keep T3's slope but get their own ceiling (.96) so passer/reader quality shows; the bias shift
# holds the population interception rate where T3 has it (calibrated, see CLAUDE_T3_RECOVERY_PLAN.md).
rep("r=md?duel(.75*eff(c,'pass')+.25*movement,eff(md,'intercept'),bias,passCtx):",
    "r=md?(RF.B4t&&action==='pass'?(()=>{const q=probability(.75*eff(c,'pass')+.25*movement,eff(md,'intercept'),bias-B4SHIFT,passCtx),p=lim(logistic(q.calc.logit),.12,.96),roll=R();return {...q,p,roll,win:roll<p};})():duel(.75*eff(c,'pass')+.25*movement,eff(md,'intercept'),bias,passCtx)):")
s = s.replace("B4SHIFT", "0.45")
# B5: a carry into a cell an available defender already occupies is checked (no progress; he engages next action)
rep("let scramble=false,", "let checked=false,scramble=false,")
rep("if(action==='carry'){x=Math.min(3,x+1);lane=(lane+Math.floor(R()*3)+2)%3;t+=P.dt.dribble;tire(c,'sprint');c.pos=S.world(zone(),poss);emit({type:'carry',team:poss,actor:c.id,zone:zone(),from:zb,calc:{weights}});return;}",
    "if(action==='carry'){const ox=x;x=Math.min(3,x+1);lane=(lane+Math.floor(R()*3)+2)%3;t+=P.dt.dribble;tire(c,'sprint');let outcome;if(RF.B5){const dest=S.world(zone(),poss),blocker=T[1-poss].ps.find(q=>q.oop===0&&S.dist(q.pos,dest)===0);if(blocker){x=ox;checked=true;outcome='checked';}}c.pos=S.world(zone(),poss);emit({type:'carry',team:poss,actor:c.id,zone:zone(),from:zb,outcome,calc:{weights}});return;}")
# M1: tempo no longer scales with MC-TE (Codex's unreviewed T3.1 choice); tactic tempo only
rep("tempo:tac.tempo*lim(1+(raw.MC-raw.TE)/a.tempoScale,.85,1.15)", "tempo:tac.tempo*(RF.M1?1:lim(1+(raw.MC-raw.TE)/a.tempoScale,.85,1.15))")
# M2: a normal pass goes to the best option (progress + space) with probability set by the passer's vision; otherwise any mate
rep("const receiver=action==='through'||action==='outlet'?runner:mates[Math.floor(R()*mates.length)],",
    "const receiver=action==='through'||action==='outlet'?runner:RF.M2?(()=>{const open=q=>Math.min(2,...T[1-poss].ps.filter(d2=>d2.oop===0).map(d2=>S.dist(d2.pos,q.pos)),2),score=q=>(S.oriented(q.pos,poss)-x)+open(q),best=mates.slice().sort((a,b)=>score(b)-score(a))[0];return R()<lim((c.c.vision-60)/40,.2,.9)?best:mates[Math.floor(R()*mates.length)];})():mates[Math.floor(R()*mates.length)],")
rep("window.CageEngine={VERSION:'cage-t3-3',",
    "window.CageEngine={VERSION:'t3r-'+(Object.keys(RF).filter(k=>RF[k]).join('+')||'none'),")
open(D + 'engine-t3-research.src.js', 'w', encoding='utf8').write(s)
print('patched OK')
